using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;using UnityEngine;using UnityEngine.UI;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI{public sealed class LocationStateRecordPresentationTests{const string CatalogJson="{\"entries\": [{\"key\": \"life.location-state.library.morning.name\", \"ko\": \"\\uc870\\uc6a9\\ud55c \\ub3c4\\uc11c\\uad00\", \"en\": \"Quiet library\"}, {\"key\": \"life.location-state.library.morning.description\", \"ko\": \"\\ucc45\\uc7a5 \\uc0ac\\uc774\\uc5d0\\uc11c \\ucc28\\ubd84\\ud788 \\uc77d\\uc744\\uac70\\ub9ac\\ub97c \\ucc3e\\uc544\\ubcf4\\uc138\\uc694.\", \"en\": \"Take your time browsing the shelves.\"}, {\"key\": \"life.location-state.library.afternoon.name\", \"ko\": \"\\uc790\\ub8cc \\uc5f4\\ub78c \\uacf5\\uac04\", \"en\": \"Reference tables\"}, {\"key\": \"life.location-state.library.afternoon.description\", \"ko\": \"\\uc77d\\uae30\\ub97c \\ub9c8\\ucce4\\uc5b4\\uc694. \\uc5f4\\ub78c\\ub300\\uc5d0\\uc11c \\uc0c8\\ub85c\\uc6b4 \\ub2e8\\uc11c\\ub97c \\uc0b4\\ud3b4\\ubcf4\\uc138\\uc694.\", \"en\": \"Your reading has opened up new leads at the reference tables.\"}, {\"key\": \"life.location-state.library.evening.name\", \"ko\": \"\\uc800\\ub141\\uc758 \\uae30\\ub85d\\uc2e4\", \"en\": \"Evening archive\"}, {\"key\": \"life.location-state.library.evening.description\", \"ko\": \"\\ud558\\ub8e8\\uac00 \\uc800\\ubb3c\\uba70 \\uae30\\ub85d\\uc2e4\\ub3c4 \\ucc28\\ubd84\\ud574\\uc84c\\uc5b4\\uc694.\", \"en\": \"The archive grows quiet as the day winds down.\"}, {\"key\": \"life.location-state.record.hidden\", \"ko\": \"\\uc544\\uc9c1 \\ubc1d\\ud600\\uc9c0\\uc9c0 \\uc54a\\uc740 \\uae30\\ub85d\", \"en\": \"Undiscovered record\"}, {\"key\": \"life.location-state.record.unknown\", \"ko\": \"\\ubc29\\ubb38\\ud55c \\uc7a5\\uc18c\\uc758 \\ubcc0\\ud654\", \"en\": \"Place update\"}, {\"key\": \"life.location-state.record.location\", \"ko\": \"\\ub9c8\\uc744\", \"en\": \"Town\"}, {\"key\": \"life.location-state.record.time\", \"ko\": \"\\ubc29\\ubb38 \\uc2dc\\uac04\", \"en\": \"Visit time\"}, {\"key\": \"life.location-state.record.detail\", \"ko\": \"{0}\\uc77c\\ucc28 \\u00b7 {1} \\u00b7 {2}\", \"en\": \"Day {0} \\u00b7 {1} \\u00b7 {2}\"}, {\"key\": \"life.location-state.record.detail-no-day\", \"ko\": \"\\uc7a5\\uc18c {0} \\u00b7 \\uc2dc\\uac04 {1}\", \"en\": \"Place {0} \\u00b7 Time {1}\"}, {\"key\": \"life.library.archive-door.action\", \"ko\": \"\\uc7a0\\uae34 \\uae30\\ub85d\\uc2e4 \\ubb38 \\uc0b4\\ud3b4\\ubcf4\\uae30\", \"en\": \"Inspect the locked archive door\"}, {\"key\": \"life.library.archive-door.result\", \"ko\": \"\\uae30\\ub85d\\uc2e4 \\ubb38\\uc740 \\uc7a0\\uaca8 \\uc788\\uc5b4\\uc694. \\ubb38\\ud2c8 \\uac00\\uae4c\\uc774 \\ub193\\uc778 \\ub0a1\\uc740 \\uc0ac\\uc9c4\\uc5d0\\ub294 \\uc9c0\\uae08\\uacfc \\uc870\\uae08 \\ub2e4\\ub978 \\ub9c8\\uc744 \\ud48d\\uacbd\\uc774 \\ubcf4\\uc5ec\\uc694. \\ud750\\ub824\\uc9c4 \\ub0a0\\uc9dc\\ub294 \\uc77d\\uc744 \\uc218 \\uc5c6\\uc9c0\\ub9cc, \\uc0ac\\uc11c\\uc5d0\\uac8c \\uc774 \\uc0ac\\uc9c4 \\uc774\\uc57c\\uae30\\ub97c \\ubb3c\\uc5b4\\ubcf4\\uace0 \\uc2f6\\uc5b4\\uc84c\\uc5b4\\uc694.\", \"en\": \"The archive door is locked. An old photograph beside the gap shows a town that looks different. The faded date is unreadable. Perhaps the librarian knows its story.\"}, {\"key\": \"fixture.state.name\", \"ko\": \"\\ucc28\\ubd84\\ud55c \\uacf5\\uac04\", \"en\": \"Quiet place\"}, {\"key\": \"fixture.state.description\", \"ko\": \"\\uc77d\\uc744\\uac70\\ub9ac\\ub97c \\ucc3e\\uc544\\ubcf4\\uc138\\uc694.\", \"en\": \"Browse something to read.\"}, {\"key\": \"fixture.location.name\", \"ko\": \"\\ub3c4\\uc11c\\uad00\", \"en\": \"Library\"}, {\"key\": \"fixture.time.name\", \"ko\": \"\\uc624\\uc804\", \"en\": \"Morning\"}]}";GameDataRegistry registry,previous;GameTextCatalog catalog;string language;GameObject canvas;readonly List<Object> owned=new List<Object>();[SetUp]public void Setup(){GameDataRegistryProvider.TryGet(out previous);language=GameText.Language;GameText.Language="ko";registry=ScriptableObject.CreateInstance<GameDataRegistry>();catalog=ScriptableObject.CreateInstance<GameTextCatalog>();owned.Add(registry);owned.Add(catalog);catalog.ConfigureJson(CatalogJson);Set("_textCatalog",catalog);GameDataRegistryProvider.SetOverrideForTests(registry);canvas=new GameObject("LocationRecordTestCanvas",typeof(RectTransform),typeof(Canvas));}[TearDown]public void Cleanup(){Object.DestroyImmediate(canvas);GameDataRegistryProvider.SetOverrideForTests(previous);GameText.Language=language;foreach(var o in owned)if(o!=null)Object.DestroyImmediate(o);owned.Clear();}
[TestCase("ko")][TestCase("en")]public void CurrentAuthoredTitleReplacesStaleSavedLabelWithoutChangingSaveData(string lang){GameText.Language=lang;RegisteredState();var summary=Summary("Old English cached label");string before=JsonUtility.ToJson(summary);foreach(string text in Render(summary)){Assert.That(text,Does.Contain(catalog.Get("fixture.state.name",lang)));Assert.That(text,Does.Contain(catalog.Get("fixture.location.name",lang)));Assert.That(text,Does.Contain(catalog.Get("fixture.time.name",lang)));Assert.That(text,Does.Not.Contain("Old English cached label"));NoIds(text);}Assert.That(JsonUtility.ToJson(summary),Is.EqualTo(before),"Presentation must not migrate or rewrite stored progress");}
[TestCase("ko")][TestCase("en")]public void HiddenRecordDoesNotRevealItsStoredOrRegisteredName(string lang){GameText.Language=lang;RegisteredState();var summary=Summary("Spoiler title");summary.Hidden=true;foreach(var text in Render(summary)){Assert.That(text,Does.Contain(catalog.Get("life.location-state.record.hidden",lang)));Assert.That(text,Does.Not.Contain("Spoiler title").And.Not.Contain(catalog.Get("fixture.state.name",lang)));NoIds(text);}}
[Test]public void UnknownCustomCachedNameRemainsReadableWithoutDebugIdentifiers(){foreach(var text in Render(Summary("Custom remembered place"))){Assert.That(text,Does.Contain("Custom remembered place"));NoIds(text);}}
[Test]public void EmptyUnknownRecordUsesUsefulLocalizedFallbackAndNoZeroDay(){var summary=Summary(string.Empty);summary.Day=0;foreach(var text in Render(summary)){Assert.That(text,Does.Contain(catalog.Get("life.location-state.record.unknown","ko")));Assert.That(text,Does.Not.Contain("0일차"));NoIds(text);}}
[TestCase("ko")][TestCase("en")]public void StandaloneStateSurfaceResolvesKeysAndUsesSharedKoreanFont(string lang){GameText.Language=lang;var state=RegisteredState();var panel=LocationStatePanel.EnsureInScene(canvas.GetComponent<Canvas>());panel.Show(new LocationStateSummaryModel("fixture.location",state,new[]{"fixture.state"},"fixture.state.name","fixture.state.description",false,Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>()));var text=panel.GetTextForTests();Assert.That(text,Does.Contain(catalog.Get("fixture.state.name",lang)).And.Contain(catalog.Get("fixture.state.description",lang)));var shared=(Font)typeof(LocationIdentityPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared").GetValue(null);foreach(var label in panel.GetComponentsInChildren<Text>(true))Assert.That(label.font,Is.SameAs(shared));}
LocationStateDefinition RegisteredState(){var location=ScriptableObject.CreateInstance<LocationDefinition>();owned.Add(location);location.ConfigureForTests("fixture.location","fixture.location.name",Vector2.zero,Array.Empty<DiscoveryDefinition>());var time=ScriptableObject.CreateInstance<TimeSlotDefinition>();owned.Add(time);time.ConfigureForTests("fixture.time","fixture.time.name",0);var state=ScriptableObject.CreateInstance<LocationStateDefinition>();owned.Add(state);state.ConfigureForTests("fixture.state","fixture.state.name","fixture.state.description",location,0,Array.Empty<LocationStateConditionBase>(),Array.Empty<LocationStateEffectBase>());Set("_locations",new[]{location});Set("_timeSlots",new[]{time});Set("_locationStates",new[]{state});return state;}
LocationStateTodaySummarySaveData Summary(string title)=>new LocationStateTodaySummarySaveData{LocationId="fixture.location",StateId="fixture.state",TimeSlotId="fixture.time",DisplayName=title,Day=4,Hidden=false};
string[] Render(LocationStateTodaySummarySaveData summary){var day=StudentDayResultPanel.EnsureInScene(canvas.GetComponent<Canvas>());day.ShowLocationStates(new[]{summary});var log=LocationStateLogPanel.EnsureInScene(canvas.GetComponent<Canvas>());log.Show(new[]{summary});return new[]{day.GetLocationStateTextForTests(),log.TextForTests};}void Set(string field,object value)=>typeof(GameDataRegistry).GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(registry,value);static void NoIds(string text){Assert.That(text,Does.Not.Contain("fixture.state").And.Not.Contain("fixture.location").And.Not.Contain("fixture.time"));}
}}
